// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // Fuzz the from address and a nonzero uint v; we will also fuzz the length of _tos
    // but since arrays cannot be fuzzed directly in this harness signature, we fuzz a uint that we use
    // to decide whether to pass an empty array or a non-empty one. The distinguishing property is about
    // empty _tos: reference reverts, mutant does not.
    function testFuzz_property(address from, uint256 v, uint256 tosFlag) public {
        // keep v wide but bounded to avoid extreme gas usage
        v = bound(v, 0, type(uint256).max);

        // Build either an empty array or a non-empty array depending on tosFlag LSB
        address[] memory tosEmpty = new address[](0);
        address[] memory tosOne = new address[](1);
        tosOne[0] = address(0xABCD);

        bool useEmpty = (tosFlag & 1) == 1;

        bool ok;
        if (useEmpty) {
            // When _tos is empty, the reference contract requires revert; capture whether call succeeded
            try c.transfer(from, address(0x1234), tosEmpty, v) {
                ok = true;
            } catch {
                ok = false;
            }
            // The universal property: for all inputs with an empty _tos, the reference contract MUST revert (ok == false).
            // The mutant (missing require) will allow ok == true for some inputs; thus this assertion will fail on the mutant.
            assertTrue(!ok);
        } else {
            // For non-empty array, both reference and mutant return true and do not revert; check it succeeds
            try c.transfer(from, address(0x1234), tosOne, v) {
                ok = true;
            } catch {
                ok = false;
            }
            // sanity: both should succeed for non-empty
            assertTrue(ok);
        }
    }
}
